#include <algorithm>
#include <array>
#include <fstream>
#include <vector>
using namespace std;
int main() {
    ifstream in("shell.in");
    ofstream out("shell.out");
    int n;
    in >> n;
    vector<array<int, 3>> steps(n);
    for (auto &step : steps) in >> step[0] >> step[1] >> step[2];
    int answer = 0;
    for (int initial = 1; initial <= 3; ++initial) {
        int position = initial, score = 0;
        for (const auto &step : steps) {
            int a = step[0], b = step[1], guessed = step[2];
            if (position == a) position = b;
            else if (position == b) position = a;
            if (position == guessed) ++score;
        }
        answer = max(answer, score);
    }
    out << answer << '\n';
}
