#include <fstream>
#include <vector>
using namespace std;
int main() {
    ifstream in("sleepy.in");
    ofstream out("sleepy.out");
    int n;
    in >> n;
    vector<int> order(n);
    for (int &cow : order) in >> cow;
    int prefix = n - 1;
    while (prefix > 0 && order[prefix - 1] < order[prefix]) --prefix;
    out << prefix << '\n';
}
