#include <algorithm>
#include <fstream>
#include <string>
#include <unordered_set>
#include <vector>
using namespace std;
int main() {
    ifstream in("guess.in");
    ofstream out("guess.out");
    int n;
    in >> n;
    vector<unordered_set<string>> traits(n);
    for (int i = 0; i < n; ++i) {
        string animal;
        int count;
        in >> animal >> count;
        for (int j = 0; j < count; ++j) {
            string trait;
            in >> trait;
            traits[i].insert(trait);
        }
    }
    int common = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            int shared = 0;
            for (const string &trait : traits[i]) if (traits[j].count(trait)) ++shared;
            common = max(common, shared);
        }
    }
    out << common + 1 << '\n';
}
